def f(n: int) -> int:
    """Return the number of prime numbers strictly less than n (n ≤ 10000)."""
    if n <= 2:
        return 0
    sieve = [True] * n
    sieve[0] = sieve[1] = False
    limit = int(n ** 0.5) + 1
    for p in range(2, limit):
        if sieve[p]:
            step = p
            start = p * p
            sieve[start:n:step] = [False] * ((n - 1 - start) // step + 1)
    return sum(sieve)
